    "styleCode": "// gold-leaf deco: a centre line drops, nested arches and sunburst rays draw outward, letters reveal with a sheen\nfunction gold(x0, y0, x1, y1, shift) { const g = ctx.createLinearGradient(x0, y0, x1, y1); g.addColorStop(0, COL.c3); g.addColorStop(clamp(.35 + shift * .3), COL.c1); g.addColorStop(clamp(.5 + shift * .3), COL.c2); g.addColorStop(clamp(.65 + shift * .3), COL.c1); g.addColorStop(1, COL.c3); return g; }\nfunction draw(t) {\n  bg(COL.bg);\n  const sh = Math.sin(t / DUR * TAU), lw = Math.max(1.5, U * .0035);\n  const R = Math.min(W * .42, U * .42), base = CY + R * .55;\n  ctx.strokeStyle = gold(CX - R, base - R, CX + R, base, sh); ctx.lineWidth = lw; ctx.lineCap = 'butt';\n  // 1. centre line drops\n  const p1 = ease.inOut(prog(t, 0, .7));\n  ctx.beginPath(); ctx.moveTo(CX, H * .04); ctx.lineTo(CX, lerp(H * .04, base - R * 1.12, p1)); ctx.stroke();\n  // 2. nested arches\n  for (let k = 0; k < 5; k++) {\n    const p = ease.inOut(prog(t, .6 + k * .12, 1.4 + k * .12)); if (p <= 0) continue;\n    const r = R * (1 - k * .16);\n    ctx.beginPath(); ctx.moveTo(CX - r, base); ctx.lineTo(CX - r, base - r * .35);\n    ctx.arc(CX, base - r * .35, r, Math.PI, Math.PI + Math.PI * p * .5); ctx.stroke();\n    ctx.beginPath(); ctx.moveTo(CX + r, base); ctx.lineTo(CX + r, base - r * .35);\n    ctx.arc(CX, base - r * .35, r, 0, -Math.PI * p * .5, true); ctx.stroke();\n  }\n  // 3. sunburst rays inside the inner arch\n  const p3 = ease.out(prog(t, 1.5, 2.4)), rin = R * .2, rout = R * .34;\n  for (let k = 0; k <= 16; k++) { const a = Math.PI + k / 16 * Math.PI, pr = clamp(p3 * 17 - k * .5); if (pr <= 0) continue;\n    ctx.beginPath(); ctx.moveTo(CX + Math.cos(a) * rin, base - R * .2 + Math.sin(a) * rin); ctx.lineTo(CX + Math.cos(a) * lerp(rin, rout, pr), base - R * .2 + Math.sin(a) * lerp(rin, rout, pr)); ctx.stroke(); }\n  // stepped base + side fans\n  const p4 = ease.out(prog(t, 1.2, 2));\n  for (let k = 0; k < 3; k++) { const w = R * (1.25 + k * .14) * p4; ctx.beginPath(); ctx.moveTo(CX - w, base + k * U * .025); ctx.lineTo(CX + w, base + k * U * .025); ctx.stroke(); }\n  // diamond finial\n  const p5 = ease.back(prog(t, 2.1, 2.5)); if (p5 > 0) { const y = base - R * 1.12, d = U * .025 * p5; ctx.fillStyle = gold(CX - d, y - d, CX + d, y + d, sh); ctx.beginPath(); ctx.moveTo(CX, y - d * 1.6); ctx.lineTo(CX + d, y); ctx.lineTo(CX, y + d * 1.6); ctx.lineTo(CX - d, y); ctx.fill(); }\n  // 4. letters reveal one by one, wide-tracked\n  if (TEXT) {\n    const letters = [...TEXT.toUpperCase()], s = Math.min(R * .3, (R * 1.5) / letters.length); font(300, s, '\"Josefin Sans\",\"Futura\",\"Didot\",' + SERIF);\n    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n    const sp = s * 1.15, x0 = CX - (letters.length - 1) * sp / 2, ty = base - R * .62;\n    letters.forEach((c, i) => { const p = ease.out(prog(t, 2.3 + i * .12, 2.8 + i * .12)); if (p <= 0) return; ctx.globalAlpha = p; ctx.fillStyle = gold(x0 - sp, ty - s, x0 + letters.length * sp, ty + s, sh * 1.5); ctx.fillText(c, x0 + i * sp, ty + (1 - p) * s * .3); });\n    ctx.globalAlpha = 1;\n  }\n  if (SUB) { const p = ease.out(prog(t, 3, 3.6)); font(400, U * .024, SERIF); ctx.textAlign = 'center'; ctx.globalAlpha = p; ctx.fillStyle = COL.c1; ctx.fillText((/[\\u0600-\\u06FF]/.test(SUB) ? SUB : SUB.toUpperCase().split(\"\").join(\" \")), CX, base + U * .11); ctx.globalAlpha = 1; }\n  // frame corners\n  const pc = ease.out(prog(t, .2, 1)), m = U * .05, cl = U * .12 * pc;\n  ctx.strokeStyle = COL.c1; for (const [x, y, sx, sy] of [[m, m, 1, 1], [W - m, m, -1, 1], [m, H - m, 1, -1], [W - m, H - m, -1, -1]]) { ctx.beginPath(); ctx.moveTo(x, y + cl * sy); ctx.lineTo(x, y); ctx.lineTo(x + cl * sx, y); ctx.stroke(); ctx.beginPath(); ctx.moveTo(x + U * .015 * sx, y + cl * .6 * sy); ctx.lineTo(x + U * .015 * sx, y + U * .015 * sy); ctx.lineTo(x + cl * .6 * sx, y + U * .015 * sy); ctx.stroke(); }\n}"
