    "descriptionEn": "Make ASCII art: a spinning 3D torus drawn only with text characters on a green-phosphor CRT, plus a typed terminal prompt. Use for dev, hacker, AI and retro-computing content.",
    "styleCode": "// spinning ASCII torus (donut.c) on a green phosphor CRT, with a typed prompt line\nconst RAMP = '.,-~:;=!*#$@';\nconst COLS = Math.round(W / (U / 64)), cw = W / COLS, ch = cw * 1.9, ROWS = Math.floor(H / ch);\nfunction draw(t) {\n  bg(COL.bg);\n  const A = t / DUR * TAU * 2 + 1, B = t / DUR * TAU + .5;\n  const zb = new Float32Array(COLS * ROWS), out = new Int8Array(COLS * ROWS).fill(-1);\n  const cA = Math.cos(A), sA = Math.sin(A), cB = Math.cos(B), sB = Math.sin(B);\n  const K2 = 5, size = Math.min(COLS, ROWS * 1.9) * .3, K1 = size * K2 * 3 / 8;\n  const ox = COLS / 2, oy = ROWS * .46;\n  for (let th = 0; th < TAU; th += .05) {\n    const ct = Math.cos(th), st = Math.sin(th);\n    for (let ph = 0; ph < TAU; ph += .018) {\n      const cp = Math.cos(ph), sp = Math.sin(ph), cx = 2 + ct, cy = st;\n      const x = cx * (cB * cp + sA * sB * sp) - cy * cA * sB, y = cx * (sB * cp - sA * cB * sp) + cy * cA * cB, z = K2 + cA * cx * sp + cy * sA, oz = 1 / z;\n      const xp = (ox + K1 * oz * x) | 0, yp = (oy - K1 * oz * y / 1.9) | 0;\n      const L = cp * ct * sB - cA * ct * sp - sA * st + cB * (cA * st - ct * sA * sp);\n      if (xp < 0 || xp >= COLS || yp < 0 || yp >= ROWS || L <= 0) continue;\n      const k = yp * COLS + xp; if (oz > zb[k]) { zb[k] = oz; out[k] = Math.min(11, (L * 8) | 0); }\n    }\n  }\n  font(700, ch * .82, MONO); ctx.textAlign = 'center'; ctx.textBaseline = 'middle';\n  ctx.shadowColor = COL.c1; ctx.shadowBlur = U * .012;\n  const intro = prog(t, 0, .5);\n  for (let r = 0; r < ROWS; r++) for (let c = 0; c < COLS; c++) {\n    const v = out[r * COLS + c]; if (v < 0) continue;\n    if (r / ROWS > intro * 1.2) continue;                 // scan-in reveal\n    ctx.fillStyle = v > 8 ? COL.c3 : v > 3 ? COL.c1 : COL.c2;\n    ctx.fillText(RAMP[v], c * cw + cw / 2, r * ch + ch / 2);\n  }\n  // typed prompt\n  if (TEXT) {\n    const n = Math.floor(clamp((t - .6) / 1.4) * TEXT.length), cur = Math.floor(t * 2.5) % 2 ? '█' : ' ';\n    font(700, U * .045, MONO); ctx.textAlign = 'left'; ctx.fillStyle = COL.c1;\n    ctx.fillText(TEXT.slice(0, n).replace(/_$/, '') + cur, W * .08, H - Math.max(ch * 3, U * .12));\n  }\n  if (SUB) { font(400, U * .026, MONO); ctx.textAlign = 'left'; ctx.fillStyle = COL.c2; ctx.fillText(SUB, W * .08, H - Math.max(ch * 3, U * .12) + U * .055); }\n  ctx.shadowBlur = 0;\n  // scanlines + vignette\n  if (!ALPHA) {\n    ctx.fillStyle = 'rgba(0,0,0,.25)'; for (let y = 0; y < H; y += 4) ctx.fillRect(0, y, W, 2);\n    const g = ctx.createRadialGradient(CX, CY, U * .3, CX, CY, Math.hypot(CX, CY)); g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,.65)'); ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);\n    const ry = ((t * .35) % 1) * H; const rb = ctx.createLinearGradient(0, ry - U * .1, 0, ry); rb.addColorStop(0, hexA(COL.c1, 0)); rb.addColorStop(1, hexA(COL.c1, .06)); ctx.fillStyle = rb; ctx.fillRect(0, ry - U * .1, W, U * .1);\n  }\n}"
