    "descriptionEn": "Make a Bauhaus geometric grid: circles, quarter circles, half-discs, triangles and stripes in primary red, yellow, blue and black that rotate and flip on a beat. Use for design, art, architecture and bold brand loops.",
    "styleCode": "// Bauhaus grid: primary geometric tiles that rotate, flip and swap on a beat\nconst COLSN = 4, ROWSN = Math.max(4, Math.round(4 * H / W));\nconst cell = Math.min(W * .88 / COLSN, H * .8 / ROWSN), gw = cell * COLSN, gh = cell * ROWSN;\nconst PAL = [COL.c1, COL.c2, COL.c3, COL.c4];\nreseed(16);\nconst tiles = []; for (let i = 0; i < COLSN * ROWSN; i++) tiles.push({ k: (rnd() * 6) | 0, c: (rnd() * 4) | 0, c2: (rnd() * 4) | 0, r: (rnd() * 4) | 0, d: rnd() });\nfunction shape(k, s, col, col2) {\n  const h = s / 2; ctx.fillStyle = col;\n  if (k === 0) { ctx.beginPath(); ctx.arc(0, 0, h * .9, 0, TAU); ctx.fill(); }\n  if (k === 1) { ctx.beginPath(); ctx.arc(-h, h, s, -Math.PI / 2, 0); ctx.lineTo(-h, h); ctx.fill(); }          // quarter circle\n  if (k === 2) { ctx.beginPath(); ctx.arc(0, h, h, Math.PI, 0); ctx.fill(); ctx.fillStyle = col2; ctx.beginPath(); ctx.arc(0, -h, h, 0, Math.PI); ctx.fill(); } // two halves\n  if (k === 3) { ctx.beginPath(); ctx.moveTo(-h, h); ctx.lineTo(h, h); ctx.lineTo(-h, -h); ctx.fill(); }        // triangle\n  if (k === 4) { ctx.fillRect(-h, -h, s, s); ctx.fillStyle = col2 === col ? COL.bg : col2; ctx.beginPath(); ctx.arc(0, 0, h * .45, 0, TAU); ctx.fill(); }\n  if (k === 5) { for (let i = 0; i < 3; i++) ctx.fillRect(-h, -h + i * s / 3 + s / 12, s, s / 6); }               // stripes\n}\nfunction draw(t) {\n  bg(COL.bg);\n  const x0 = CX - gw / 2, y0 = CY - gh / 2, beat = DUR / 6;\n  tiles.forEach((tl, i) => {\n    const cx = x0 + (i % COLSN + .5) * cell, cy = y0 + (Math.floor(i / COLSN) + .5) * cell;\n    const intro = ease.back(prog(t, tl.d * .6, tl.d * .6 + .45));\n    const b = Math.floor(t / beat), lt = (t % beat) / beat;\n    const turn = ((b + i) % 3 === 0) ? ease.inOut(prog(lt, .1, .45)) : 0;  // rotate 90° on some beats\n    const rot = (tl.r + b * (((i % 3) === 0) ? 1 : 0) + turn) * Math.PI / 2;\n    const flipK = ((i * 7 + b) % 5 === 0);\n    const k = flipK && lt > .5 ? (tl.k + b) % 6 : (tl.k + (flipK ? b - 1 : 0) + 6) % 6;\n    const sx = flipK ? Math.abs(Math.cos(clamp((lt - .3) / .4) * Math.PI)) : 1;\n    ctx.save(); ctx.beginPath(); ctx.rect(cx - cell / 2, cy - cell / 2, cell, cell); ctx.clip();\n    ctx.translate(cx, cy); ctx.rotate(rot); ctx.scale(intro * sx, intro);\n    const col = PAL[(tl.c + (flipK && lt > .5 ? 1 : 0)) % 4], col2 = PAL[(tl.c2 + 1) % 4];\n    shape(k, cell * .98, col, col2 === col ? PAL[(tl.c2 + 2) % 4] : col2);\n    ctx.restore();\n  });\n  ctx.strokeStyle = COL.c4; ctx.lineWidth = Math.max(2, U * .006); ctx.strokeRect(x0, y0, gw, gh);\n  if (TEXT) { const s = fitFont(TEXT.toLowerCase(), 800, U * .1, gw); ctx.textAlign = 'left'; ctx.fillStyle = COL.c4; ctx.fillText(TEXT.toLowerCase(), x0, y0 - s * .35); }\n  if (SUB) { font(600, U * .03); ctx.textAlign = 'right'; ctx.fillStyle = COL.c4; ctx.fillText(SUB.toLowerCase(), x0 + gw, y0 + gh + U * .05); }\n}"
